function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));}
function escapeAttr(value){return escapeHtml(value).replace(/`/g,'&#96;');}
function formatTime(ms=0){const seconds=Math.max(0,Number(ms||0))/1000;const minutes=Math.floor(seconds/60);return`${String(minutes).padStart(2,'0')}:${(seconds%60).toFixed(1).padStart(4,'0')}`;}
function coreState(){return globalThis.VocabMasterApp?.getState?.()||{cards:[],settings:{},fsrsConfig:{},metrics:{}};}
function mountSpatialPrompt(panel,prompt,{kind='reading'}={}){
  if(!panel||!prompt||!['diagram','plan','map'].includes(prompt.mode)||!Number.isSafeInteger(prompt.width)||!Number.isSafeInteger(prompt.height))return;
  const form=panel.querySelector('form');if(!form)return;const section=document.createElement('section'),svgNs='http://www.w3.org/2000/svg',svg=document.createElementNS(svgNs,'svg'),title=document.createElementNS(svgNs,'title'),description=document.createElementNS(svgNs,'desc');
  section.className='objective-spatial-prompt';section.dataset.spatialReading=kind==='reading'?prompt.mode:'';section.dataset.spatialListening=kind==='listening'?prompt.mode:'';title.id=`objective-spatial-title-${kind}`;title.textContent=prompt.title;description.id=`objective-spatial-description-${kind}`;description.textContent=prompt.description;svg.setAttribute('role','img');svg.setAttribute('aria-labelledby',`${title.id} ${description.id}`);svg.setAttribute('viewBox',`0 0 ${prompt.width} ${prompt.height}`);svg.setAttribute('preserveAspectRatio','xMidYMid meet');svg.append(title,description);
  for(const element of prompt.elements){let node;if(element.kind==='line'){node=document.createElementNS(svgNs,'line');for(const key of ['x1','y1','x2','y2'])node.setAttribute(key,String(element[key]));}else if(element.kind==='rect'){node=document.createElementNS(svgNs,'rect');for(const key of ['x','y','width','height'])node.setAttribute(key,String(element[key]));node.setAttribute('rx','2');const label=document.createElementNS(svgNs,'text');label.setAttribute('x',String(element.x+4));label.setAttribute('y',String(element.y+16));label.textContent=element.label;svg.append(label);}else if(element.kind==='polyline'){node=document.createElementNS(svgNs,'polyline');const points=element.closed?[...element.points,element.points[0]]:element.points;node.setAttribute('points',points.map(point=>`${point.x},${point.y}`).join(' '));node.setAttribute('fill','none');node.setAttribute('data-closed',String(element.closed));}else if(element.kind==='text'){node=document.createElementNS(svgNs,'text');node.setAttribute('x',String(element.x));node.setAttribute('y',String(element.y));node.textContent=element.text;}if(node){node.setAttribute('data-spatial-element',element.kind);svg.append(node);}}
  const anchorList=document.createElement('div');anchorList.className='objective-spatial-anchor-list';for(const anchor of prompt.anchors){const marker=document.createElementNS(svgNs,'circle'),label=document.createElementNS(svgNs,'text'),descriptionNode=document.createElement('span');marker.setAttribute('cx',String(anchor.x));marker.setAttribute('cy',String(anchor.y));marker.setAttribute('r','3');marker.setAttribute('data-spatial-anchor',anchor.slotId);label.setAttribute('x',String(anchor.x+4));label.setAttribute('y',String(anchor.y-4));label.textContent=anchor.label;svg.append(marker,label);descriptionNode.id=`objective-spatial-anchor-${kind}-${anchor.slotId}`;descriptionNode.textContent=anchor.label;anchorList.append(descriptionNode);const control=[...form.querySelectorAll('input,select')].find(value=>value.name===`${kind==='reading'?'reading-owner-slot':'wave4-matching'}-${anchor.slotId}`||value.name?.endsWith(`-${anchor.slotId}`));if(control)control.setAttribute('aria-describedby',[control.getAttribute('aria-describedby'),descriptionNode.id].filter(Boolean).join(' '));}
  section.append(svg,anchorList);form.before(section);
}
function activeCards(){return(coreState().cards||[]).filter(card=>!card.suspendedAt&&!card.archivedAt);}
function findCard(id){return(coreState().cards||[]).find(card=>card.id===id)||null;}
function dispatchCards(cards){const current=coreState();globalThis.dispatchEvent(new CustomEvent('vocab:external-change',{detail:{reason:'ielts-lab',state:{...current,cards}}}));}
function showStatus(message,kind='info'){state.status=String(message||'');state.statusKind=kind;const node=$('#ieltsLabStatus');if(node){node.className=`ielts-status ${kind}`;node.textContent=state.status;}}
function setBusy(value,message=''){state.busy=Boolean(value);const dialog=$('#ieltsLabDialog');if(dialog)$$('button, input, textarea, select',dialog).forEach(control=>{if(control.dataset.keepEnabled!=='true')control.disabled=state.busy;});if(message)showStatus(message,'loading');}
function cardOptions(selected=''){return`<option value="">Không liên kết thẻ</option>${activeCards().map(card=>`<option value="${escapeAttr(card.id)}" ${card.id===selected?'selected':''}>${escapeHtml(card.front)} — ${escapeHtml(card.back)}</option>`).join('')}`;}
function currentMediaSegment(){return state.segments.find(segment=>segment.id===state.currentSegmentId)||state.segments[0]||null;}

async function callIeltsApi(path,payload,{timeoutMs=130_000}={}){
  const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),timeoutMs);const current=coreState();const headers={'content-type':'application/json','x-gemini-model':current.settings?.model||'gemini-3.6-flash'};const key=sessionStorage.getItem(SESSION_KEY)||'';if(key)headers['x-gemini-key']=key;
  try{const response=await fetch(path,{method:'POST',headers,body:JSON.stringify(payload),signal:controller.signal});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`IELTS API lỗi HTTP ${response.status}`);return data;}
  catch(error){if(error.name==='AbortError')throw new Error('AI xử lý quá lâu. Dữ liệu cục bộ vẫn được giữ để thử lại.');throw error;}finally{clearTimeout(timer);}
}

async function seedCuratedContent(){
  const existingSets=new Set((await listIeltsRecords(IELTS_STORE_NAMES.lexicalSets)).map(row=>row.id));
  for(const item of CURATED_LEXICAL_SETS)if(!existingSets.has(item.id))await saveIeltsRecord(IELTS_STORE_NAMES.lexicalSets,{...sanitizeLexicalSet(item),suggestedEntries:structuredClone(item.suggestedEntries||[])},'ielts-curated-set-seeded');
  const existingLabs=new Set((await listIeltsRecords(IELTS_STORE_NAMES.labItems)).map(row=>row.id));
  for(const item of CURATED_PARAPHRASE_ITEMS)if(!existingLabs.has(item.id))await saveLabItem(item);
  const existingReadings=new Set((await listIeltsRecords(IELTS_STORE_NAMES.readingPassages)).map(row=>row.id));
  for(const item of CURATED_READING_PASSAGES)if(!existingReadings.has(item.id))await saveReadingPassage(item);
}

